namespace Driftstack {
std::span<const RealtimeAnalyserOverrideEntry> realtimeAnalyserOverrideTable()
{
    return std::span<const RealtimeAnalyserOverrideEntry>(kRealtimeAnalyserOverrideTableData);
}
} // namespace Driftstack

namespace Driftstack {

namespace {

class DecodedAnalyserBytes : public RefCounted<DecodedAnalyserBytes> {
public:
    static Ref<DecodedAnalyserBytes> create() { return adoptRef(*new DecodedAnalyserBytes); }
    Vector<uint8_t> bytes;
};

Lock& cacheLock()
{
    static NeverDestroyed<Lock> lock;
    return lock.get();
}

// Cache keyed on the const char* pointer of each base64 string in the
// table. Each kRealtimeAnalyserOverrideTable[i].XBytesBase64 is a
// unique global; pointer equality is stable across calls.
HashMap<const char*, RefPtr<DecodedAnalyserBytes>>& cache()
{
    static NeverDestroyed<HashMap<const char*, RefPtr<DecodedAnalyserBytes>>> map;
    return map.get();
}

RefPtr<DecodedAnalyserBytes> decodeOnce(const char* base64Data)
{
    auto view = StringView::fromLatin1(base64Data);
    auto decoded = base64Decode(view, { Base64DecodeOption::ValidatePadding });
    if (!decoded)
        return nullptr;
    auto buf = DecodedAnalyserBytes::create();
    buf->bytes = WTF::move(decoded.value());
    return buf;
}

const char* base64ForKind(const RealtimeAnalyserOverrideEntry& entry, AnalyserBufferKind kind)
{
    switch (kind) {
    case AnalyserBufferKind::FloatFrequency: return entry.floatFreqBytesBase64;
    case AnalyserBufferKind::ByteFrequency: return entry.byteFreqBytesBase64;
    case AnalyserBufferKind::FloatTimeDomain: return entry.floatTimeBytesBase64;
    case AnalyserBufferKind::ByteTimeDomain: return entry.byteTimeBytesBase64;
    }
    return nullptr;
}

} // anonymous

bool isRealtimeAnalyserOverrideEnabled()
{
    static const bool enabled = []() {
        const char* env = std::getenv("DRIFTSTACK_REALTIME_ANALYSER_OVERRIDE");
        return env && env[0] == '1';
    }();
    return enabled;
}

bool getRealtimeAnalyserOverrideBytes(uint32_t sampleRate, uint32_t fftSize, AnalyserBufferKind kind, std::span<const uint8_t>& outBytes)
{
    // Bounded linear scan via std::span (no raw indexing — satisfies
    // -Wunsafe-buffer-usage). Table is small (≤ ~8 topologies); O(N)
    // fine. First match wins; codegen sorts most-specific archetype first.
    for (const auto& entry : realtimeAnalyserOverrideTable()) {
        if (entry.sampleRate != sampleRate || entry.fftSize != fftSize)
            continue;
        const char* base64Data = base64ForKind(entry, kind);
        if (!base64Data)
            return false;
        Locker locker(cacheLock());
        auto& map = cache();
        auto it = map.find(base64Data);
        if (it == map.end()) {
            auto decoded = decodeOnce(base64Data);
            if (!decoded)
                return false;
            it = map.set(base64Data, decoded.copyRef()).iterator;
        }
        if (!it->value)
            return false;
        outBytes = it->value->bytes.span();
        return true;
    }
    return false;
}

} // namespace Driftstack
